"""
Exhaustive certification of the small values of U(n).

U(n) is the least number of points of a poset containing every n-element poset
as an induced subposet.  This script settles n = 0, 1, 2, 3 completely by brute
force and reproduces the lower bound 7 for n = 4:

    * it enumerates every partial order on n labelled points
      (1, 1, 3, 19, 219 of them for n = 0..4);
    * it enumerates every partial order on N labelled points for N up to 5 and
      tests each as a candidate host, searching all N^n placements;
    * it prints the smallest N that works, together with the Hasse diagram of a
      witnessing host;
    * it independently confirms the structural lower bound U(n) >= 2n - 1 by
      computing, exhaustively, the largest poset embedding as an induced
      subposet into both the n-chain and the n-antichain (the answer is 1).

Self-contained; standard library only.
"""

from __future__ import annotations

from itertools import combinations, permutations, product
from typing import List, Sequence, Tuple

Relation = Tuple[Tuple[bool, ...], ...]


def is_partial_order(r: Relation) -> bool:
    n = len(r)
    if any(not r[x][x] for x in range(n)):
        return False
    for x in range(n):
        for y in range(n):
            if x != y and r[x][y] and r[y][x]:
                return False
            if r[x][y] and any(r[y][z] and not r[x][z] for z in range(n)):
                return False
    return True


def all_partial_orders(n: int) -> List[Relation]:
    if n == 0:
        return [tuple()]
    off = [(x, y) for x in range(n) for y in range(n) if x != y]
    out: List[Relation] = []
    for bits in product([False, True], repeat=len(off)):
        t = [[x == y for y in range(n)] for x in range(n)]
        for (x, y), b in zip(off, bits):
            t[x][y] = b
        r: Relation = tuple(tuple(row) for row in t)
        if is_partial_order(r):
            out.append(r)
    return out


def embeds(r: Relation, host: Relation) -> bool:
    n, N = len(r), len(host)
    for f in product(range(N), repeat=n):
        if all(host[f[x]][f[y]] == r[x][y] for x in range(n) for y in range(n)):
            return True
    return False


def is_universal(host: Relation, orders: Sequence[Relation]) -> bool:
    return all(embeds(r, host) for r in orders)


def smallest_host(n: int, max_N: int = 5) -> Tuple[int, Relation | None]:
    orders = all_partial_orders(n)
    for N in range(n, max_N + 1):
        for host in all_partial_orders(N):
            if is_universal(host, orders):
                return N, host
    return -1, None


def covers(r: Relation) -> List[Tuple[int, int]]:
    n = len(r)
    return [
        (x, y)
        for x in range(n)
        for y in range(n)
        if x != y and r[x][y]
        and not any(z not in (x, y) and r[x][z] and r[z][y] for z in range(n))
    ]


def max_common_induced(a: Relation, b: Relation) -> int:
    n = len(a)
    for size in range(n, 0, -1):
        for A in combinations(range(n), size):
            for phi in permutations(range(n), size):
                if all(
                    a[A[i]][A[j]] == b[phi[i]][phi[j]]
                    for i in range(size)
                    for j in range(size)
                ):
                    return size
    return 0


def main() -> None:
    print("number of partial orders on n labelled points:")
    for n in range(5):
        print(f"   n = {n}:  {len(all_partial_orders(n)) if n <= 4 else '?'}")
    print()

    print("smallest universal host, found by exhaustive search:")
    for n in range(4):
        N, host = smallest_host(n, max_N=5)
        cov = covers(host) if host else []
        desc = ", ".join(f"{x}<{y}" for x, y in cov) or "antichain"
        print(f"   U({n}) = {N}      witness cover relations: {desc}")
    print("   U(4): search space too large here; 7 <= U(4) <= 8 is known,")
    print("         the lower bound from the overlap principle below.")
    print()

    print("overlap principle, verified exhaustively:")
    print(f"{'n':>3} {'max common induced (chain, antichain)':>40} {'2n-s':>8}")
    for n in range(2, 7):
        ch: Relation = tuple(tuple(x <= y for y in range(n)) for x in range(n))
        an: Relation = tuple(tuple(x == y for y in range(n)) for x in range(n))
        s = max_common_induced(ch, an)
        print(f"{n:>3} {s:>40} {2*n - s:>8}")
    print()
    print("The overlap bound 2n-1 is exact for n <= 3 and gives U(4) >= 7.")


if __name__ == "__main__":
    main()

