"""
Algorithm B: Tagged-Neighbourhood Labelling for two-level hierarchies.

Realises every (k, l)-bipartite poset inside one fixed host on k + 2^k * l
points, with labels of k + ceil(log2 l) + 1 bits.  On balanced parts this is
n/2 + O(log n) bits per element -- the exponent n/2.
"""

from __future__ import annotations
from typing import Dict, FrozenSet, List, Set, Tuple

Label = Tuple[str, int, int]  # ("bot", index, 0) or ("top", neighbourhood_mask, tag)


def tagged_labels(k: int, l: int, R: Set[Tuple[int, int]]) -> Dict[str, Label]:
    """
    Label the (k,l)-bipartite poset with relation R (pairs (i, j) meaning a_i < b_j).

        a_i  |->  ("bot", i, 0)
        b_j  |->  ("top", N_R(j), j)      where N_R(j) = { i : (i,j) in R }

    Cost: O(kl).  Label length: k + ceil(log2 l) + 1 bits.
    """
    labels: Dict[str, Label] = {}
    for i in range(k):
        labels[f"a{i}"] = ("bot", i, 0)
    for j in range(l):
        mask = 0
        for i in range(k):
            if (i, j) in R:
                mask |= 1 << i
        labels[f"b{j}"] = ("top", mask, j)
    return labels


def decode_leq(u: Label, v: Label) -> bool:
    """
    Decoder, depending only on the two labels:
        bottom i <= top (S, t)   iff  bit i of S is set;
        equal labels are comparable; nothing else is.
    """
    if u == v:
        return True
    if u[0] == "bot" and v[0] == "top":
        return bool((v[1] >> u[1]) & 1)
    return False


def host_size(k: int, l: int) -> int:
    """|B(k,l)| = k + 2^k * l."""
    return k + (1 << k) * l


def counting_floor(k: int, l: int) -> float:
    """No (k,l)-bipartite-universal host has fewer than 2^(kl/(k+l)) points."""
    return 2.0 ** (k * l / (k + l)) if k + l else 0.0


def verify_all(k: int, l: int) -> bool:
    """
    Exhaustive check over all 2^(kl) relations R: the labelling is injective and
    reproduces the order exactly.
    """
    from itertools import product

    pairs = [(i, j) for i in range(k) for j in range(l)]
    for bits in product([0, 1], repeat=len(pairs)):
        R = {p for p, b in zip(pairs, bits) if b}
        lab = tagged_labels(k, l, R)
        names = list(lab)
        if len(set(lab.values())) != len(names):
            return False
        for x in names:
            for y in names:
                if x == y:
                    expected = True
                elif x.startswith("a") and y.startswith("b"):
                    expected = (int(x[1:]), int(y[1:])) in R
                else:
                    expected = False
                if decode_leq(lab[x], lab[y]) != expected:
                    return False
    return True


if __name__ == "__main__":
    k, l = 3, 3
    print("host size k + 2^k*l =", host_size(k, l))
    print("counting floor 2^(kl/(k+l)) = %.3f" % counting_floor(k, l))
    print("exhaustive verification over all 2^%d relations:" % (k * l), verify_all(k, l))
    print()
    print("balanced parts, n = 2m:")
    print(f"{'m':>4} {'host m*2^m+m':>16} {'floor 2^(m/2)':>16}")
    for m in (1, 2, 4, 8, 16):
        print(f"{m:>4} {host_size(m, m):>16} {counting_floor(m, m):>16.2f}")
